toolScript:
let currentSection = 0;
        let quizAnswers = [];
        let memoryLevel = 1;
        let memorySequence = [];
        let userSequence = [];
        let memoryScore = 0;
        let attentionHits = 0;
        let attentionInterval;
        let attentionTimer;
        let attentionTimeLeft = 30;
        let targetNumber = 5;
        let targetVisible = false;

        const quizQuestions = [
            { q: "How many hours per day do you spend on screens (phone, computer, TV)?", options: ["Less than 2 hours", "2-4 hours", "4-8 hours", "More than 8 hours"] },
            { q: "How often do you use your phone in the hour before bed?", options: ["Never or rarely", "Sometimes", "Often", "Every night"] },
            { q: "Do you rely on your phone's GPS even for familiar routes?", options: ["Never", "Rarely", "Sometimes", "Always"] },
            { q: "How often do you find yourself scrolling without purpose?", options: ["Rarely", "Sometimes", "Often", "Very frequently"] },
            { q: "Do you struggle to remember phone numbers of close family/friends?", options: ["No, I remember them", "Some of them", "Only a few", "I rely on my phone for all contacts"] },
            { q: "How many social media apps do you have on your phone?", options: ["1-3 apps", "4-6 apps", "7-10 apps", "More than 10 apps"] },
            { q: "How often do you check notifications immediately?", options: ["Rarely", "Sometimes", "Often", "Instantly, always"] },
            { q: "Do you find it difficult to focus on one task without checking your phone?", options: ["Never", "Rarely", "Sometimes", "Very often"] }
        ];

        function initQuiz() {
            const container = document.getElementById('quiz-container');
            container.innerHTML = '';
            quizQuestions.forEach((item, idx) => {
                const div = document.createElement('div');
                div.className = 'quiz-option';
                div.innerHTML = `
                    <span class="w-6 h-6 bg-cognitive-light rounded-full flex items-center justify-center text-xs font-bold text-cognitive-DEFAULT">${idx + 1}</span>
                    <span class="flex-1">${item.q}</span>
                `;
                div.onclick = () => selectQuizOption(idx, div);
                container.appendChild(div);
            });
        }

        function selectQuizOption(idx, element) {
            const options = element.parentElement.querySelectorAll('.quiz-option');
            options.forEach(opt => opt.classList.remove('selected'));
            element.classList.add('selected');
            quizAnswers[idx] = parseInt(element.querySelector('span:first-child').textContent) - 1;
        }

        function nextSection() {
            if (currentSection === 0) {
                if (quizAnswers.length < quizQuestions.length) {
                    alert('Please answer all questions before proceeding.');
                    return;
                }
                document.getElementById('quiz-section').classList.add('hidden');
                document.getElementById('memory-section').classList.remove('hidden');
                currentSection = 1;
                document.getElementById('main-btn').textContent = 'Continue to Attention Test';
            } else if (currentSection === 1) {
                document.getElementById('memory-section').classList.add('hidden');
                document.getElementById('attention-section').classList.remove('hidden');
                currentSection = 2;
                document.getElementById('main-btn').textContent = 'View Results';
            } else if (currentSection === 2) {
                showResults();
            }
        }

        function initMemoryGrid() {
            const grid = document.getElementById('memory-grid');
            grid.innerHTML = '';
            for (let i = 0; i < 16; i++) {
                const cell = document.createElement('div');
                cell.className = 'memory-cell disabled';
                cell.dataset.index = i;
                cell.onclick = () => clickMemoryCell(i);
                grid.appendChild(cell);
            }
        }

        function startMemoryTest() {
            initMemoryGrid();
            memorySequence = [];
            userSequence = [];
            const levelSize = Math.min(2 + memoryLevel, 5);
            for (let i = 0; i < levelSize; i++) {
                let idx;
                do {
                    idx = Math.floor(Math.random() * 16);
                } while (memorySequence.includes(idx));
                memorySequence.push(idx);
            }
            document.getElementById('memory-start-btn').disabled = true;
            document.getElementById('memory-start-btn').style.opacity = '0.5';
            playMemorySequence();
        }

        function playMemorySequence() {
            const cells = document.querySelectorAll('.memory-cell');
            let i = 0;
            const interval = setInterval(() => {
                cells.forEach(c => c.classList.remove('active'));
                if (i < memorySequence.length) {
                    cells[memorySequence[i]].classList.add('active');
                    i++;
                } else {
                    clearInterval(interval);
                    setTimeout(() => {
                        cells.forEach(c => {
                            c.classList.remove('active', 'disabled');
                        });
                    }, 500);
                }
            }, 600);
        }

        function clickMemoryCell(idx) {
            const cells = document.querySelectorAll('.memory-cell');
            if (cells[idx].classList.contains('disabled')) return;
            userSequence.push(idx);
            cells[idx].classList.add('active');
            setTimeout(() => cells[idx].classList.remove('active'), 300);
            if (userSequence.length === memorySequence.length) {
                checkMemoryResult();
            }
        }

        function checkMemoryResult() {
            const cells = document.querySelectorAll('.memory-cell');
            let correct = true;
            for (let i = 0; i < memorySequence.length; i++) {
                if (memorySequence[i] === userSequence[i]) {
                    cells[memorySequence[i]].classList.add('correct');
                } else {
                    cells[userSequence[i]].classList.add('incorrect');
                    correct = false;
                }
            }
            if (correct) {
                memoryScore += memoryLevel * 10;
                memoryLevel++;
                document.getElementById('memory-score').textContent = memoryScore;
                document.getElementById('memory-level').textContent = memoryLevel;
            } else {
                document.getElementById('memory-start-btn').disabled = false;
                document.getElementById('memory-start-btn').style.opacity = '1';
            }
        }

        function startAttentionTest() {
            attentionHits = 0;
            attentionTimeLeft = 30;
            document.getElementById('attention-hits').textContent = attentionHits;
            document.getElementById('attention-time').textContent = attentionTimeLeft;
            document.getElementById('attention-start-btn').disabled = true;
            document.getElementById('attention-start-btn').style.opacity = '0.5';
            moveTarget();
            attentionInterval = setInterval(moveTarget, 1000);
            attentionTimer = setInterval(() => {
                attentionTimeLeft--;
                document.getElementById('attention-time').textContent = attentionTimeLeft;
                if (attentionTimeLeft <= 0) {
                    stopAttentionTest();
                }
            }, 1000);
        }

        function moveTarget() {
            const target = document.getElementById('attention-target');
            const tracker = document.getElementById('attention-tracker');
            const maxX = tracker.offsetWidth - 50;
            const maxY = tracker.offsetHeight - 50;
            target.style.left = (Math.random() * maxX) + 'px';
            target.style.top = (Math.random() * maxY) + 'px';
            targetNumber = Math.floor(Math.random() * 9) + 1;
            document.getElementById('target-number').textContent = targetNumber;
            if (targetNumber === 5) {
                attentionHits++;
                document.getElementById('attention-hits').textContent = attentionHits;
            }
        }

        function hitTarget() {
            attentionHits++;
            document.getElementById('attention-hits').textContent = attentionHits;
            moveTarget();
        }

        function stopAttentionTest() {
            clearInterval(attentionInterval);
            clearInterval(attentionTimer);
            document.getElementById('attention-start-btn').disabled = false;
            document.getElementById('attention-start-btn').style.opacity = '1';
        }

        function showResults() {
            document.getElementById('attention-section').classList.add('hidden');
            document.getElementById('main-btn').classList.add('hidden');
            const resultsSection = document.getElementById('results-section');
            resultsSection.classList.remove('hidden');
            const quizScore = quizAnswers.reduce((sum, val, idx) => sum + (quizQuestions[idx].options.length - val), 0);
            const normalizedScore = Math.round((quizScore / (quizQuestions.length * 4)) * 100);
            const memoryBonus = Math.min(memoryScore, 20);
            const attentionBonus = Math.min(attentionHits * 2, 20);
            const totalScore = Math.round(normalizedScore * 0.6 + memoryBonus * 0.2 + attentionBonus * 0.2);
            document.getElementById('risk-score').textContent = totalScore;
            document.getElementById('risk-indicator').style.left = (totalScore - 5) + '%';
            let riskLevel = 'Low';
            let recommendations = 'Great job! Your cognitive health is in good shape. Continue to engage in analog activities and maintain balanced screen time habits.';
            if (totalScore >= 50 && totalScore < 70) {
                riskLevel = 'Moderate';
                recommendations = 'Your results suggest some cognitive strain from digital device use. Consider reducing screen time, taking regular breaks, and engaging in more memory-challenging activities.';
            } else if (totalScore >= 70) {
                riskLevel = 'High';
                recommendations = 'Your results indicate significant cognitive impact from digital device use. We strongly recommend reducing screen time, practicing memory exercises, and seeking analog activities.';
            }
            document.getElementById('risk-level').textContent = riskLevel;
            document.getElementById('recommendations').textContent = recommendations;
            document.getElementById('test-status-text').textContent = 'Complete';
        }

        initQuiz();
        initMemoryGrid();
